-- ============================================
-- 历史数据修正（兼容旧库：补 space_id / tenant_id / 生命周期字段 / 分类归一化）
-- ============================================

-- 修正历史错误关系：导数的前置知识应为函数（原 9->10 方向错误）
UPDATE `knowledge_relation` SET `source_id` = 10, `target_id` = 9
WHERE `id` = 8 AND `source_id` = 9 AND `target_id` = 10 AND `relation_type` = 'PRE';

-- 历史知识点补默认知识空间，并归一化学科分类
UPDATE `knowledge_base` SET `space_id` = 1 WHERE `tenant_id` = 1 AND `space_id` IS NULL AND `id` BETWEEN 1 AND 13;
UPDATE `knowledge_base` SET `category` = 'PHYSICS' WHERE `tenant_id` = 1 AND `category` = 'PHYS';
UPDATE `knowledge_base` SET `category` = 'ENGLISH' WHERE `tenant_id` = 1 AND `category` = 'ENG';

-- 历史关系补默认知识空间
UPDATE `knowledge_relation` SET `space_id` = 1, `tenant_id` = COALESCE(`tenant_id`, 1)
WHERE `space_id` IS NULL AND `id` BETWEEN 1 AND 8;

-- 历史文档补默认知识空间与生命周期字段
UPDATE `knowledge_document` SET `space_id` = 1, `lifecycle_status` = COALESCE(`lifecycle_status`, 'PUBLISHED'),
`parse_status` = COALESCE(`parse_status`, 'READY'), `storage_provider` = COALESCE(`storage_provider`, 'local')
WHERE `space_id` IS NULL AND `id` BETWEEN 1 AND 2;

-- 历史文档关联补租户与空间（兼容 V020 已回填 tenant 但 space 仍为空的情况）
UPDATE `knowledge_doc_relation` SET `tenant_id` = COALESCE(`tenant_id`, 1)
WHERE `tenant_id` IS NULL;
UPDATE `knowledge_doc_relation` SET `space_id` = 1
WHERE `space_id` IS NULL AND `tenant_id` = 1;

-- 补齐种子文档的当前版本号
UPDATE `knowledge_document` d SET `current_version_id` = d.`id`
WHERE d.`id` BETWEEN 1 AND 22 AND d.`current_version_id` IS NULL
  AND EXISTS (SELECT 1 FROM `knowledge_document_version` v WHERE v.`id` = d.`id`);
