INSERT IGNORE INTO `knowledge_document` (`id`, `space_id`, `title`, `content`, `doc_type`, `source`, `author`, `lifecycle_status`, `parse_status`, `storage_provider`, `object_key`, `mime_type`, `file_size`, `checksum`, `current_version_id`, `tenant_id`, `create_by`, `update_by`) VALUES
(1, 1, '自然数概念', '自然数是指用以计量事物的件数或表示事物次序的数。即用数码0,1,2,3,4,……所表示的数。', 'ARTICLE', '人教版数学七年级上册', '教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/1.txt', 'text/plain', 119, 'f78a850b4de603049e7b635bc6e6c6ecd7430139b07a4ea5cbe02cb5f0ca2f65', 1, 1, 'system', 'system'),
(2, 1, '绝对值的定义', '绝对值是一个数在数轴上对应的点到原点的距离，用符号|a|表示。', 'ARTICLE', '人教版数学七年级上册', '教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/2.txt', 'text/plain', 88, 'de821cc61a1eb0aeaa06bd9fbfa4676dd35f435555e451817f6fb8a02308d570', 2, 1, 'system', 'system'),
(3, 1, '有理数的运算', '有理数的加减乘除运算是初中数学的基础。同号两数相加，取相同的符号，并把绝对值相加；异号两数相加，取绝对值较大的加数的符号，并用较大的绝对值减去较小的绝对值。有理数乘法法则：两数相乘，同号得正，异号得负，并把绝对值相乘。除以一个不等于零的数，等于乘这个数的倒数。运算中常用的运算律有加法交换律、加法结合律和乘法分配律。', 'ARTICLE', '人教版数学七年级上册', '教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/3.txt', 'text/plain', 475, '7a3f02f73920ba720e5baa61b7b7dc8726354728ed77d849e2738ae1d4c521f4', 3, 1, 'system', 'system'),
(4, 1, '一元一次方程的解法', '只含有一个未知数，并且未知数的最高次数是1的整式方程叫做一元一次方程，一般形式为 ax+b=0（a≠0）。解一元一次方程的步骤：1.去分母；2.去括号；3.移项；4.合并同类项；5.系数化为1。移项时要注意变号，等式两边同时加或减同一个数（或式子），等式仍然成立。', 'ARTICLE', '人教版数学七年级上册', '教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/4.txt', 'text/plain', 355, '647c877c51919b88a17b2f79007d006130159be376c24081d9eea4ee2a6a9a7b', 4, 1, 'system', 'system'),
(5, 1, '函数与一次函数', '一般地，在一个变化过程中有两个变量x与y，如果对于x的每一个确定的值，y都有唯一确定的值与其对应，那么就说y是x的函数。一次函数的一般形式为 y=kx+b（k≠0），当b=0时，y=kx 是正比例函数。一次函数的图象是一条直线，k决定直线的倾斜方向，b决定直线与y轴的交点位置。', 'ARTICLE', '人教版数学八年级下册', '教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/5.txt', 'text/plain', 366, '7b668df0a7d41bdf68c01c27ded5d02d05f0d6f6ab1414f6c6ae66ac4653f66b', 5, 1, 'system', 'system'),
(6, 1, '二次函数的图象与性质', '二次函数的一般形式为 y=ax²+bx+c（a≠0），图象是一条抛物线。a>0时开口向上，a<0时开口向下。对称轴为直线 x=-b/(2a)，顶点坐标为 (-b/(2a), (4ac-b²)/(4a))。求二次函数解析式常用一般式、顶点式和交点式三种方法。', 'ARTICLE', '人教版数学九年级上册', '教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/6.txt', 'text/plain', 279, '61efdccba39a39b50ef69ed27ea547c8e243c68a429bf049ec8c96f4f9eff09b', 6, 1, 'system', 'system'),
(7, 1, '全等三角形的判定', '能够完全重合的两个三角形叫做全等三角形，全等三角形的对应边相等、对应角相等。判定两个三角形全等的方法有：SSS（三边对应相等）、SAS（两边及其夹角对应相等）、ASA（两角及其夹边对应相等）、AAS（两角及其中一角的对边对应相等）、HL（斜边和一条直角边对应相等的两个直角三角形）。', 'ARTICLE', '人教版数学八年级上册', '教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/7.txt', 'text/plain', 396, 'dffed592caa76a63477ca0233b3eb10c08a5d0edf4166d3d4ca404bf2ef1d960', 7, 1, 'system', 'system'),
(8, 1, '圆的性质与切线', '圆是平面内到定点的距离等于定长的点的集合。圆既是轴对称图形又是中心对称图形，任何一条直径所在的直线都是它的对称轴。垂直于弦的直径平分弦及其所对的弧。切线判定定理：经过半径的外端并且垂直于这条半径的直线是圆的切线。切线长定理：从圆外一点引圆的两条切线，它们的切线长相等。', 'ARTICLE', '人教版数学九年级上册', '教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/8.txt', 'text/plain', 403, '18250c94709bcd14b365f2ae96cd3d04bc6fafc29e50a4a5240dd7ba9b526a9b', 8, 1, 'system', 'system'),
(9, 1, '声音的产生与传播', '声音是由物体的振动产生的，正在发声的物体叫做声源。声音的传播需要介质，固体、液体、气体都能传声，真空不能传声。声速与介质的种类和温度有关，15℃的空气中声速约为340m/s。声音在传播过程中遇到障碍物会发生反射，形成回声，可以利用回声测距。', 'ARTICLE', '人教版物理八年级上册', '物理教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/9.txt', 'text/plain', 345, '30b1ca820bf2703758e6b2615e96980eedf5a0c9713060bf1b21d9b7182d599f', 9, 1, 'system', 'system'),
(10, 1, '光的反射与折射', '光在同种均匀介质中沿直线传播。光的反射定律：反射光线、入射光线和法线在同一平面内，反射光线和入射光线分居法线两侧，反射角等于入射角。光的折射：光从一种介质斜射入另一种介质时，传播方向会发生偏折。折射角随入射角的增大而增大，光从空气斜射入水中时折射角小于入射角。', 'ARTICLE', '人教版物理八年级上册', '物理教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/10.txt', 'text/plain', 391, '7ca8d2a5d25d4ec145995d8d31852593f66641ca7c95f6d65aa4b9ecd94c1daf', 10, 1, 'system', 'system'),
(11, 1, '压强与浮力', '压强表示压力的作用效果，公式为 p=F/S。增大压强的方法：增大压力或减小受力面积；减小压强的方法相反。液体压强与液体密度和深度有关，公式为 p=ρgh。浮力产生的原因是物体上下表面受到液体的压力差。阿基米德原理：浸在液体中的物体受到向上的浮力，浮力大小等于它排开液体的重力，即 F浮=ρ液gV排。', 'ARTICLE', '人教版物理八年级下册', '物理教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/11.txt', 'text/plain', 414, '6f2a1a5b0751fb65d22215a8354f7e3aa5e69ad33fc3437e0a236fbc06bbdb23', 11, 1, 'system', 'system'),
(12, 1, '欧姆定律', '欧姆定律：导体中的电流，跟导体两端的电压成正比，跟导体的电阻成反比，表达式为 I=U/R。串联电路中电流处处相等，总电压等于各部分电压之和；并联电路中各支路电压相等，干路电流等于各支路电流之和。使用伏安法测电阻时，电流表与被测电阻串联，电压表与被测电阻并联。', 'ARTICLE', '人教版物理九年级全一册', '物理教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/12.txt', 'text/plain', 376, '48545b4fb3f6c9ac78a88038de9454076710a9b9e60689263b451ddb05ea131c', 12, 1, 'system', 'system'),
(13, 1, '化学式与化合价', '用元素符号表示物质组成的式子叫做化学式。化合价是元素在化合时表现出来的性质，常见化合价：氢为+1价，氧为-2价，钠为+1价，钙为+2价等。在化合物中正负化合价的代数和为零。书写化学式时，正价元素在前、负价元素在后，例如 H2O、CO2、NaOH。', 'ARTICLE', '人教版化学九年级上册', '化学教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/13.txt', 'text/plain', 332, '40eddfe2ba4d907c808d3980f63ec67a0d2d76bea30cdaaa6229f9177ce43e25', 13, 1, 'system', 'system'),
(14, 1, '质量守恒定律与化学方程式', '参加化学反应的各物质的质量总和，等于反应后生成的各物质的质量总和，这就是质量守恒定律。从微观角度看，化学反应前后原子的种类、数目和质量都不变。化学方程式是用化学式表示化学反应的式子，书写化学方程式时要注意配平，使反应前后各元素的原子个数相等，遵循质量守恒定律。', 'ARTICLE', '人教版化学九年级上册', '化学教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/14.txt', 'text/plain', 391, 'bfe7be9b763213a366c85ecf3fdc26a1579d387dda101e80a7edda864f1204d6', 14, 1, 'system', 'system'),
(15, 1, '初中语文常见修辞手法', '常见修辞手法包括比喻、拟人、夸张、排比、对偶、反问、设问、借代等。比喻用相似的事物打比方，使表达更加生动形象；拟人把物当作人来写，赋予物以人的动作、情感；排比把结构相同或相似、内容相关的三个或三个以上句子排列在一起，增强语势；反问用疑问的形式表达确定的意思，加强语气。', 'ARTICLE', '人教版语文七年级上册', '语文教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/15.txt', 'text/plain', 403, '504511e518a934a0c62539721448e2efd2bb43fe5beaad085ba7c1e6fe31a120', 15, 1, 'system', 'system'),
(16, 1, '文言文常见虚词', '文言文常见虚词有之、其、而、以、于、为、乃、则等。之可作代词、助词（的）或动词（到）；其常作代词，可译为他的、它的；而表示并列、承接、转折、修饰等关系；以可作介词（用、凭借）和连词（来）；于表示在、从、对、比等意思。理解虚词要结合具体语境，注意一词多义。', 'ARTICLE', '人教版语文八年级上册', '语文教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/16.txt', 'text/plain', 382, '815fbba799e5251719cdd693a9d0635320f5f0303a092892878fb62bb28cf249', 16, 1, 'system', 'system'),
(17, 1, '英语动词时态总览', '英语常见时态有：一般现在时表示经常性动作或客观事实，一般过去时表示过去发生的事，一般将来时用 will 或 be going to 加动词原形，现在进行时用 am/is/are 加动词的现在分词，过去进行时用 was/were 加现在分词，现在完成时用 have/has 加过去分词。解题时要注意时间状语与时态的搭配。', 'ARTICLE', '人教版英语七年级全册', '英语教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/17.txt', 'text/plain', 378, '43162843aa7d84a30313f51e5bd2a3dc13eed80b62e35e1da42b1cee3b82ef40', 17, 1, 'system', 'system'),
(18, 1, '被动语态讲解', '被动语态表示主语是动作的承受者，构成形式为 be 加过去分词。一般现在时的被动语态用 am/is/are 加过去分词，一般过去时的被动语态用 was/were 加过去分词，含情态动词的被动语态用情态动词加 be 加过去分词。把主动语态改为被动语态时，宾语变主语，谓语动词变过去分词，原主语用 by 引出。', 'ARTICLE', '人教版英语九年级全一册', '英语教研组', 'PUBLISHED', 'READY', 'local', 'seed/docs/18.txt', 'text/plain', 391, '49120dd454d915d7984cbf3c5e40e2659a778e251e5045998b55292ca010c427', 18, 1, 'system', 'system'),
(19, 2, '员工手册（试用版）', '本手册适用于公司全体员工，请认真阅读并遵照执行。第一章 公司简介：公司成立于2015年，专注于企业级人工智能解决方案，总部位于上海。第二章 考勤管理：实行每周五天工作制，工作时间为9:00-18:00，迟到、早退需提前向部门负责人报备。第三章 休假制度：员工入职满一年享有5天带薪年假，事假、病假需提前申请并提交审批。第四章 行为规范：员工应遵守保密义务，爱护公司财产，维护办公环境整洁。', 'REFERENCE', '人力资源部', '人力资源部', 'DRAFT', 'PENDING', 'local', 'seed/docs/19.txt', 'text/plain', 545, 'fe650cab9ece34eba4bbfc6e2ab091956d6a904a3fd74fd0d3e7bc499db6fd4c', 19, 1, 'system', 'system'),
(20, 2, '差旅报销管理制度', '差旅报销适用于因公出差产生的交通、住宿、餐饮等费用。交通费标准：高铁二等座、经济舱机票，超出部分自理；住宿费标准：一线城市每人每晚不超过500元，其他城市不超过350元；餐饮补助：每天100元，无需提供发票。报销流程：出差结束后5个工作日内，登录OA系统填写报销单，附发票和行程单，经部门负责人审批后由财务审核打款。', 'REFERENCE', '财务部', '财务部', 'PUBLISHED', 'READY', 'local', 'seed/docs/20.txt', 'text/plain', 451, 'bbe55a0f0c5f875738661269f16647bdf16b2647f5c6fa3f932013e097a5c9b2', 20, 1, 'system', 'system'),
(21, 2, '信息安全管理制度', '信息安全管理制度适用于公司全体员工。账号安全：员工应设置高强度密码并定期更换，严禁共享账号。数据保密：客户数据、源代码、商业计划等机密信息未经授权不得外传。终端安全：办公电脑需安装杀毒软件并保持系统更新，禁止安装盗版软件。网络安全：不得私自在办公网络接入无线路由器或代理设备。违规处理：违反本制度将视情节轻重给予警告、通报批评直至解除劳动合同。', 'REFERENCE', '信息技术部', '信息技术部', 'PUBLISHED', 'READY', 'local', 'seed/docs/21.txt', 'text/plain', 517, '948047d9c543a706bc11f7cc590478c60cb192f8cc68c61917e80a93edd2bebf', 21, 1, 'system', 'system'),
(22, 2, '招聘管理制度', '招聘流程包括需求申请、岗位发布、简历筛选、笔试面试、背景调查、录用审批、入职办理七个环节。用人部门需提前一周提交招聘需求申请，经人力资源部审核后发布岗位。面试由HR初面、业务部门复试，关键岗位需总监终面。录用审批通过后，HR发出offer并安排入职体检。新员工入职需完成入职培训并通过考核。', 'REFERENCE', '人力资源部', '人力资源部', 'PUBLISHED', 'READY', 'local', 'seed/docs/22.txt', 'text/plain', 418, '4c11a3ee291dd90bd28ec00eb7c68b5f0dbb9c2b21f1fae9808c3d8934d24271', 22, 1, 'system', 'system');
INSERT IGNORE INTO `knowledge_document_version` (`id`, `document_id`, `space_id`, `version_no`, `title`, `content`, `storage_provider`, `object_key`, `mime_type`, `file_size`, `checksum`, `lifecycle_status`, `parse_status`, `model_profile`, `published_at`, `tenant_id`, `create_by`, `update_by`) VALUES
(1, 1, 1, 1, '自然数概念', '自然数是指用以计量事物的件数或表示事物次序的数。即用数码0,1,2,3,4,……所表示的数。', 'local', 'seed/docs/1.txt', 'text/plain', 119, 'f78a850b4de603049e7b635bc6e6c6ecd7430139b07a4ea5cbe02cb5f0ca2f65', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(2, 2, 1, 1, '绝对值的定义', '绝对值是一个数在数轴上对应的点到原点的距离，用符号|a|表示。', 'local', 'seed/docs/2.txt', 'text/plain', 88, 'de821cc61a1eb0aeaa06bd9fbfa4676dd35f435555e451817f6fb8a02308d570', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(3, 3, 1, 1, '有理数的运算', '有理数的加减乘除运算是初中数学的基础。同号两数相加，取相同的符号，并把绝对值相加；异号两数相加，取绝对值较大的加数的符号，并用较大的绝对值减去较小的绝对值。有理数乘法法则：两数相乘，同号得正，异号得负，并把绝对值相乘。除以一个不等于零的数，等于乘这个数的倒数。运算中常用的运算律有加法交换律、加法结合律和乘法分配律。', 'local', 'seed/docs/3.txt', 'text/plain', 475, '7a3f02f73920ba720e5baa61b7b7dc8726354728ed77d849e2738ae1d4c521f4', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(4, 4, 1, 1, '一元一次方程的解法', '只含有一个未知数，并且未知数的最高次数是1的整式方程叫做一元一次方程，一般形式为 ax+b=0（a≠0）。解一元一次方程的步骤：1.去分母；2.去括号；3.移项；4.合并同类项；5.系数化为1。移项时要注意变号，等式两边同时加或减同一个数（或式子），等式仍然成立。', 'local', 'seed/docs/4.txt', 'text/plain', 355, '647c877c51919b88a17b2f79007d006130159be376c24081d9eea4ee2a6a9a7b', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(5, 5, 1, 1, '函数与一次函数', '一般地，在一个变化过程中有两个变量x与y，如果对于x的每一个确定的值，y都有唯一确定的值与其对应，那么就说y是x的函数。一次函数的一般形式为 y=kx+b（k≠0），当b=0时，y=kx 是正比例函数。一次函数的图象是一条直线，k决定直线的倾斜方向，b决定直线与y轴的交点位置。', 'local', 'seed/docs/5.txt', 'text/plain', 366, '7b668df0a7d41bdf68c01c27ded5d02d05f0d6f6ab1414f6c6ae66ac4653f66b', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(6, 6, 1, 1, '二次函数的图象与性质', '二次函数的一般形式为 y=ax²+bx+c（a≠0），图象是一条抛物线。a>0时开口向上，a<0时开口向下。对称轴为直线 x=-b/(2a)，顶点坐标为 (-b/(2a), (4ac-b²)/(4a))。求二次函数解析式常用一般式、顶点式和交点式三种方法。', 'local', 'seed/docs/6.txt', 'text/plain', 279, '61efdccba39a39b50ef69ed27ea547c8e243c68a429bf049ec8c96f4f9eff09b', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(7, 7, 1, 1, '全等三角形的判定', '能够完全重合的两个三角形叫做全等三角形，全等三角形的对应边相等、对应角相等。判定两个三角形全等的方法有：SSS（三边对应相等）、SAS（两边及其夹角对应相等）、ASA（两角及其夹边对应相等）、AAS（两角及其中一角的对边对应相等）、HL（斜边和一条直角边对应相等的两个直角三角形）。', 'local', 'seed/docs/7.txt', 'text/plain', 396, 'dffed592caa76a63477ca0233b3eb10c08a5d0edf4166d3d4ca404bf2ef1d960', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(8, 8, 1, 1, '圆的性质与切线', '圆是平面内到定点的距离等于定长的点的集合。圆既是轴对称图形又是中心对称图形，任何一条直径所在的直线都是它的对称轴。垂直于弦的直径平分弦及其所对的弧。切线判定定理：经过半径的外端并且垂直于这条半径的直线是圆的切线。切线长定理：从圆外一点引圆的两条切线，它们的切线长相等。', 'local', 'seed/docs/8.txt', 'text/plain', 403, '18250c94709bcd14b365f2ae96cd3d04bc6fafc29e50a4a5240dd7ba9b526a9b', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(9, 9, 1, 1, '声音的产生与传播', '声音是由物体的振动产生的，正在发声的物体叫做声源。声音的传播需要介质，固体、液体、气体都能传声，真空不能传声。声速与介质的种类和温度有关，15℃的空气中声速约为340m/s。声音在传播过程中遇到障碍物会发生反射，形成回声，可以利用回声测距。', 'local', 'seed/docs/9.txt', 'text/plain', 345, '30b1ca820bf2703758e6b2615e96980eedf5a0c9713060bf1b21d9b7182d599f', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(10, 10, 1, 1, '光的反射与折射', '光在同种均匀介质中沿直线传播。光的反射定律：反射光线、入射光线和法线在同一平面内，反射光线和入射光线分居法线两侧，反射角等于入射角。光的折射：光从一种介质斜射入另一种介质时，传播方向会发生偏折。折射角随入射角的增大而增大，光从空气斜射入水中时折射角小于入射角。', 'local', 'seed/docs/10.txt', 'text/plain', 391, '7ca8d2a5d25d4ec145995d8d31852593f66641ca7c95f6d65aa4b9ecd94c1daf', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(11, 11, 1, 1, '压强与浮力', '压强表示压力的作用效果，公式为 p=F/S。增大压强的方法：增大压力或减小受力面积；减小压强的方法相反。液体压强与液体密度和深度有关，公式为 p=ρgh。浮力产生的原因是物体上下表面受到液体的压力差。阿基米德原理：浸在液体中的物体受到向上的浮力，浮力大小等于它排开液体的重力，即 F浮=ρ液gV排。', 'local', 'seed/docs/11.txt', 'text/plain', 414, '6f2a1a5b0751fb65d22215a8354f7e3aa5e69ad33fc3437e0a236fbc06bbdb23', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(12, 12, 1, 1, '欧姆定律', '欧姆定律：导体中的电流，跟导体两端的电压成正比，跟导体的电阻成反比，表达式为 I=U/R。串联电路中电流处处相等，总电压等于各部分电压之和；并联电路中各支路电压相等，干路电流等于各支路电流之和。使用伏安法测电阻时，电流表与被测电阻串联，电压表与被测电阻并联。', 'local', 'seed/docs/12.txt', 'text/plain', 376, '48545b4fb3f6c9ac78a88038de9454076710a9b9e60689263b451ddb05ea131c', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(13, 13, 1, 1, '化学式与化合价', '用元素符号表示物质组成的式子叫做化学式。化合价是元素在化合时表现出来的性质，常见化合价：氢为+1价，氧为-2价，钠为+1价，钙为+2价等。在化合物中正负化合价的代数和为零。书写化学式时，正价元素在前、负价元素在后，例如 H2O、CO2、NaOH。', 'local', 'seed/docs/13.txt', 'text/plain', 332, '40eddfe2ba4d907c808d3980f63ec67a0d2d76bea30cdaaa6229f9177ce43e25', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(14, 14, 1, 1, '质量守恒定律与化学方程式', '参加化学反应的各物质的质量总和，等于反应后生成的各物质的质量总和，这就是质量守恒定律。从微观角度看，化学反应前后原子的种类、数目和质量都不变。化学方程式是用化学式表示化学反应的式子，书写化学方程式时要注意配平，使反应前后各元素的原子个数相等，遵循质量守恒定律。', 'local', 'seed/docs/14.txt', 'text/plain', 391, 'bfe7be9b763213a366c85ecf3fdc26a1579d387dda101e80a7edda864f1204d6', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(15, 15, 1, 1, '初中语文常见修辞手法', '常见修辞手法包括比喻、拟人、夸张、排比、对偶、反问、设问、借代等。比喻用相似的事物打比方，使表达更加生动形象；拟人把物当作人来写，赋予物以人的动作、情感；排比把结构相同或相似、内容相关的三个或三个以上句子排列在一起，增强语势；反问用疑问的形式表达确定的意思，加强语气。', 'local', 'seed/docs/15.txt', 'text/plain', 403, '504511e518a934a0c62539721448e2efd2bb43fe5beaad085ba7c1e6fe31a120', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(16, 16, 1, 1, '文言文常见虚词', '文言文常见虚词有之、其、而、以、于、为、乃、则等。之可作代词、助词（的）或动词（到）；其常作代词，可译为他的、它的；而表示并列、承接、转折、修饰等关系；以可作介词（用、凭借）和连词（来）；于表示在、从、对、比等意思。理解虚词要结合具体语境，注意一词多义。', 'local', 'seed/docs/16.txt', 'text/plain', 382, '815fbba799e5251719cdd693a9d0635320f5f0303a092892878fb62bb28cf249', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(17, 17, 1, 1, '英语动词时态总览', '英语常见时态有：一般现在时表示经常性动作或客观事实，一般过去时表示过去发生的事，一般将来时用 will 或 be going to 加动词原形，现在进行时用 am/is/are 加动词的现在分词，过去进行时用 was/were 加现在分词，现在完成时用 have/has 加过去分词。解题时要注意时间状语与时态的搭配。', 'local', 'seed/docs/17.txt', 'text/plain', 378, '43162843aa7d84a30313f51e5bd2a3dc13eed80b62e35e1da42b1cee3b82ef40', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(18, 18, 1, 1, '被动语态讲解', '被动语态表示主语是动作的承受者，构成形式为 be 加过去分词。一般现在时的被动语态用 am/is/are 加过去分词，一般过去时的被动语态用 was/were 加过去分词，含情态动词的被动语态用情态动词加 be 加过去分词。把主动语态改为被动语态时，宾语变主语，谓语动词变过去分词，原主语用 by 引出。', 'local', 'seed/docs/18.txt', 'text/plain', 391, '49120dd454d915d7984cbf3c5e40e2659a778e251e5045998b55292ca010c427', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(19, 19, 2, 1, '员工手册（试用版）', '本手册适用于公司全体员工，请认真阅读并遵照执行。第一章 公司简介：公司成立于2015年，专注于企业级人工智能解决方案，总部位于上海。第二章 考勤管理：实行每周五天工作制，工作时间为9:00-18:00，迟到、早退需提前向部门负责人报备。第三章 休假制度：员工入职满一年享有5天带薪年假，事假、病假需提前申请并提交审批。第四章 行为规范：员工应遵守保密义务，爱护公司财产，维护办公环境整洁。', 'local', 'seed/docs/19.txt', 'text/plain', 545, 'fe650cab9ece34eba4bbfc6e2ab091956d6a904a3fd74fd0d3e7bc499db6fd4c', 'DRAFT', 'PENDING', 'default', NULL, 1, 'system', 'system'),
(20, 20, 2, 1, '差旅报销管理制度', '差旅报销适用于因公出差产生的交通、住宿、餐饮等费用。交通费标准：高铁二等座、经济舱机票，超出部分自理；住宿费标准：一线城市每人每晚不超过500元，其他城市不超过350元；餐饮补助：每天100元，无需提供发票。报销流程：出差结束后5个工作日内，登录OA系统填写报销单，附发票和行程单，经部门负责人审批后由财务审核打款。', 'local', 'seed/docs/20.txt', 'text/plain', 451, 'bbe55a0f0c5f875738661269f16647bdf16b2647f5c6fa3f932013e097a5c9b2', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(21, 21, 2, 1, '信息安全管理制度', '信息安全管理制度适用于公司全体员工。账号安全：员工应设置高强度密码并定期更换，严禁共享账号。数据保密：客户数据、源代码、商业计划等机密信息未经授权不得外传。终端安全：办公电脑需安装杀毒软件并保持系统更新，禁止安装盗版软件。网络安全：不得私自在办公网络接入无线路由器或代理设备。违规处理：违反本制度将视情节轻重给予警告、通报批评直至解除劳动合同。', 'local', 'seed/docs/21.txt', 'text/plain', 517, '948047d9c543a706bc11f7cc590478c60cb192f8cc68c61917e80a93edd2bebf', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system'),
(22, 22, 2, 1, '招聘管理制度', '招聘流程包括需求申请、岗位发布、简历筛选、笔试面试、背景调查、录用审批、入职办理七个环节。用人部门需提前一周提交招聘需求申请，经人力资源部审核后发布岗位。面试由HR初面、业务部门复试，关键岗位需总监终面。录用审批通过后，HR发出offer并安排入职体检。新员工入职需完成入职培训并通过考核。', 'local', 'seed/docs/22.txt', 'text/plain', 418, '4c11a3ee291dd90bd28ec00eb7c68b5f0dbb9c2b21f1fae9808c3d8934d24271', 'PUBLISHED', 'READY', 'default', '2026-07-01 10:00:00', 1, 'system', 'system');
