INSERT IGNORE INTO `knowledge_evaluation_case` (`id`, `space_id`, `question`, `expected_doc_ids`, `expected_answer`, `tenant_id`, `create_by`, `update_by`) VALUES
(1, 1, '什么是绝对值？请解释它的几何意义。', '[2]', '绝对值是一个数在数轴上对应的点到原点的距离，用 |a| 表示，|-5|=5。', 1, 'system', 'system'),
(2, 1, '解一元一次方程的一般步骤有哪些？', '[4]', '去分母、去括号、移项、合并同类项、系数化为1。', 1, 'system', 'system'),
(3, 1, '一次函数和二次函数的图象有什么区别？', '[5,6]', '一次函数图象是一条直线，二次函数图象是一条抛物线。', 1, 'system', 'system'),
(4, 1, '声音是怎样产生的？在真空中能传播吗？', '[9]', '声音由物体振动产生，传播需要介质，真空不能传声。', 1, 'system', 'system'),
(5, 1, '欧姆定律的内容和表达式是什么？', '[12]', '导体中的电流与电压成正比、与电阻成反比，I=U/R。', 1, 'system', 'system'),
(6, 1, '什么是质量守恒定律？', '[14]', '参加反应的各物质的质量总和等于反应后生成的各物质的质量总和。', 1, 'system', 'system'),
(7, 1, '英语被动语态如何构成？', '[18]', 'be 加过去分词，时态体现在 be 动词的变化上。', 1, 'system', 'system'),
(8, 2, '员工请年假需要满足什么条件？', '[19]', '入职满一年享有5天带薪年假，需提前申请并提交审批。', 1, 'system', 'system'),
(9, 2, '差旅住宿费的报销标准是多少？', '[20]', '一线城市每人每晚不超过500元，其他城市不超过350元。', 1, 'system', 'system'),
(10, 2, '办公电脑有哪些信息安全要求？', '[21]', '安装杀毒软件、保持系统更新、禁止安装盗版软件。', 1, 'system', 'system'),
(11, 2, '招聘流程包含哪些环节？', '[22]', '需求申请、岗位发布、简历筛选、笔试面试、背景调查、录用审批、入职办理。', 1, 'system', 'system');
INSERT IGNORE INTO `vector_knowledge_chunk` (`id`, `document_id`, `space_id`, `version_id`, `content`, `metadata`, `chunk_index`, `page_number`, `section_path`, `start_offset`, `end_offset`, `token_count`, `tenant_id`, `create_by`, `update_by`) VALUES
(1, 1, 1, 1, '自然数是指用以计量事物的件数或表示事物次序的数。即用数码0,1,2,3,4,……所表示的数。', '{"docType":"ARTICLE","title":"自然数概念"}', 0, 1, '#', 0, 118, 59, 1, 'system', 'system'),
(2, 2, 1, 2, '绝对值是一个数在数轴上对应的点到原点的距离，用符号|a|表示。', '{"docType":"ARTICLE","title":"绝对值的定义"}', 0, 1, '#', 0, 87, 43, 1, 'system', 'system'),
(3, 3, 1, 3, '有理数的加减乘除运算是初中数学的基础。同号两数相加，取相同的符号，并把绝对值相加；异号两数相加，取绝对值较大的加数的符号，并用较大的绝对值减去较小的绝对值。有理数乘法法则：两数相乘，同号得正，异号得负，并把绝对值相乘。除以一个不等于零的数，等于乘这个数的倒数。运算中常用的运算律有加法交换律、加法结合律和乘法分配律。', '{"docType":"ARTICLE","title":"有理数的运算"}', 0, 1, '#', 0, 474, 237, 1, 'system', 'system'),
(4, 4, 1, 4, '只含有一个未知数，并且未知数的最高次数是1的整式方程叫做一元一次方程，一般形式为 ax+b=0（a≠0）。解一元一次方程的步骤：1.去分母；2.去括号；3.移项；4.合并同类项；5.系数化为1。移项时要注意变号，等式两边同时加或减同一个数（或式子），等式仍然成立。', '{"docType":"ARTICLE","title":"一元一次方程的解法"}', 0, 1, '#', 0, 354, 177, 1, 'system', 'system'),
(5, 5, 1, 5, '一般地，在一个变化过程中有两个变量x与y，如果对于x的每一个确定的值，y都有唯一确定的值与其对应，那么就说y是x的函数。一次函数的一般形式为 y=kx+b（k≠0），当b=0时，y=kx 是正比例函数。一次函数的图象是一条直线，k决定直线的倾斜方向，b决定直线与y轴的交点位置。', '{"docType":"ARTICLE","title":"函数与一次函数"}', 0, 1, '#', 0, 365, 182, 1, 'system', 'system'),
(6, 6, 1, 6, '二次函数的一般形式为 y=ax²+bx+c（a≠0），图象是一条抛物线。a>0时开口向上，a<0时开口向下。对称轴为直线 x=-b/(2a)，顶点坐标为 (-b/(2a), (4ac-b²)/(4a))。求二次函数解析式常用一般式、顶点式和交点式三种方法。', '{"docType":"ARTICLE","title":"二次函数的图象与性质"}', 0, 1, '#', 0, 278, 139, 1, 'system', 'system'),
(7, 7, 1, 7, '能够完全重合的两个三角形叫做全等三角形，全等三角形的对应边相等、对应角相等。判定两个三角形全等的方法有：SSS（三边对应相等）、SAS（两边及其夹角对应相等）、ASA（两角及其夹边对应相等）、AAS（两角及其中一角的对边对应相等）、HL（斜边和一条直角边对应相等的两个直角三角形）。', '{"docType":"ARTICLE","title":"全等三角形的判定"}', 0, 1, '#', 0, 395, 197, 1, 'system', 'system'),
(8, 8, 1, 8, '圆是平面内到定点的距离等于定长的点的集合。圆既是轴对称图形又是中心对称图形，任何一条直径所在的直线都是它的对称轴。垂直于弦的直径平分弦及其所对的弧。切线判定定理：经过半径的外端并且垂直于这条半径的直线是圆的切线。切线长定理：从圆外一点引圆的两条切线，它们的切线长相等。', '{"docType":"ARTICLE","title":"圆的性质与切线"}', 0, 1, '#', 0, 402, 201, 1, 'system', 'system'),
(9, 9, 1, 9, '声音是由物体的振动产生的，正在发声的物体叫做声源。声音的传播需要介质，固体、液体、气体都能传声，真空不能传声。声速与介质的种类和温度有关，15℃的空气中声速约为340m/s。声音在传播过程中遇到障碍物会发生反射，形成回声，可以利用回声测距。', '{"docType":"ARTICLE","title":"声音的产生与传播"}', 0, 1, '#', 0, 344, 172, 1, 'system', 'system'),
(10, 10, 1, 10, '光在同种均匀介质中沿直线传播。光的反射定律：反射光线、入射光线和法线在同一平面内，反射光线和入射光线分居法线两侧，反射角等于入射角。光的折射：光从一种介质斜射入另一种介质时，传播方向会发生偏折。折射角随入射角的增大而增大，光从空气斜射入水中时折射角小于入射角。', '{"docType":"ARTICLE","title":"光的反射与折射"}', 0, 1, '#', 0, 390, 195, 1, 'system', 'system'),
(11, 11, 1, 11, '压强表示压力的作用效果，公式为 p=F/S。增大压强的方法：增大压力或减小受力面积；减小压强的方法相反。液体压强与液体密度和深度有关，公式为 p=ρgh。浮力产生的原因是物体上下表面受到液体的压力差。阿基米德原理：浸在液体中的物体受到向上的浮力，浮力大小等于它排开液体的重力，即 F浮=ρ液gV排。', '{"docType":"ARTICLE","title":"压强与浮力"}', 0, 1, '#', 0, 413, 206, 1, 'system', 'system'),
(12, 12, 1, 12, '欧姆定律：导体中的电流，跟导体两端的电压成正比，跟导体的电阻成反比，表达式为 I=U/R。串联电路中电流处处相等，总电压等于各部分电压之和；并联电路中各支路电压相等，干路电流等于各支路电流之和。使用伏安法测电阻时，电流表与被测电阻串联，电压表与被测电阻并联。', '{"docType":"ARTICLE","title":"欧姆定律"}', 0, 1, '#', 0, 375, 187, 1, 'system', 'system'),
(13, 13, 1, 13, '用元素符号表示物质组成的式子叫做化学式。化合价是元素在化合时表现出来的性质，常见化合价：氢为+1价，氧为-2价，钠为+1价，钙为+2价等。在化合物中正负化合价的代数和为零。书写化学式时，正价元素在前、负价元素在后，例如 H2O、CO2、NaOH。', '{"docType":"ARTICLE","title":"化学式与化合价"}', 0, 1, '#', 0, 331, 165, 1, 'system', 'system'),
(14, 14, 1, 14, '参加化学反应的各物质的质量总和，等于反应后生成的各物质的质量总和，这就是质量守恒定律。从微观角度看，化学反应前后原子的种类、数目和质量都不变。化学方程式是用化学式表示化学反应的式子，书写化学方程式时要注意配平，使反应前后各元素的原子个数相等，遵循质量守恒定律。', '{"docType":"ARTICLE","title":"质量守恒定律与化学方程式"}', 0, 1, '#', 0, 390, 195, 1, 'system', 'system'),
(15, 15, 1, 15, '常见修辞手法包括比喻、拟人、夸张、排比、对偶、反问、设问、借代等。比喻用相似的事物打比方，使表达更加生动形象；拟人把物当作人来写，赋予物以人的动作、情感；排比把结构相同或相似、内容相关的三个或三个以上句子排列在一起，增强语势；反问用疑问的形式表达确定的意思，加强语气。', '{"docType":"ARTICLE","title":"初中语文常见修辞手法"}', 0, 1, '#', 0, 402, 201, 1, 'system', 'system'),
(16, 16, 1, 16, '文言文常见虚词有之、其、而、以、于、为、乃、则等。之可作代词、助词（的）或动词（到）；其常作代词，可译为他的、它的；而表示并列、承接、转折、修饰等关系；以可作介词（用、凭借）和连词（来）；于表示在、从、对、比等意思。理解虚词要结合具体语境，注意一词多义。', '{"docType":"ARTICLE","title":"文言文常见虚词"}', 0, 1, '#', 0, 381, 190, 1, 'system', 'system'),
(17, 17, 1, 17, '英语常见时态有：一般现在时表示经常性动作或客观事实，一般过去时表示过去发生的事，一般将来时用 will 或 be going to 加动词原形，现在进行时用 am/is/are 加动词的现在分词，过去进行时用 was/were 加现在分词，现在完成时用 have/has 加过去分词。解题时要注意时间状语与时态的搭配。', '{"docType":"ARTICLE","title":"英语动词时态总览"}', 0, 1, '#', 0, 377, 188, 1, 'system', 'system'),
(18, 18, 1, 18, '被动语态表示主语是动作的承受者，构成形式为 be 加过去分词。一般现在时的被动语态用 am/is/are 加过去分词，一般过去时的被动语态用 was/were 加过去分词，含情态动词的被动语态用情态动词加 be 加过去分词。把主动语态改为被动语态时，宾语变主语，谓语动词变过去分词，原主语用 by 引出。', '{"docType":"ARTICLE","title":"被动语态讲解"}', 0, 1, '#', 0, 390, 195, 1, 'system', 'system'),
(19, 20, 2, 20, '差旅报销适用于因公出差产生的交通、住宿、餐饮等费用。交通费标准：高铁二等座、经济舱机票，超出部分自理；住宿费标准：一线城市每人每晚不超过500元，其他城市不超过350元；餐饮补助：每天100元，无需提供发票。', '{"docType":"REFERENCE","title":"差旅报销管理制度"}', 0, 1, '#', 0, 294, 147, 1, 'system', 'system'),
(20, 20, 2, 20, '报销流程：出差结束后5个工作日内，登录OA系统填写报销单，附发票和行程单，经部门负责人审批后由财务审核打款。', '{"docType":"REFERENCE","title":"差旅报销管理制度"}', 1, 1, '#', 294, 450, 78, 1, 'system', 'system'),
(21, 21, 2, 21, '信息安全管理制度适用于公司全体员工。账号安全：员工应设置高强度密码并定期更换，严禁共享账号。数据保密：客户数据、源代码、商业计划等机密信息未经授权不得外传。终端安全：办公电脑需安装杀毒软件并保持系统更新，禁止安装盗版软件。', '{"docType":"REFERENCE","title":"信息安全管理制度"}', 0, 1, '#', 0, 333, 166, 1, 'system', 'system'),
(22, 21, 2, 21, '网络安全：不得私自在办公网络接入无线路由器或代理设备。违规处理：违反本制度将视情节轻重给予警告、通报批评直至解除劳动合同。', '{"docType":"REFERENCE","title":"信息安全管理制度"}', 1, 1, '#', 333, 516, 91, 1, 'system', 'system'),
(23, 22, 2, 22, '招聘流程包括需求申请、岗位发布、简历筛选、笔试面试、背景调查、录用审批、入职办理七个环节。用人部门需提前一周提交招聘需求申请，经人力资源部审核后发布岗位。面试由HR初面、业务部门复试，关键岗位需总监终面。', '{"docType":"REFERENCE","title":"招聘管理制度"}', 0, 1, '#', 0, 302, 151, 1, 'system', 'system'),
(24, 22, 2, 22, '录用审批通过后，HR发出offer并安排入职体检。新员工入职需完成入职培训并通过考核。', '{"docType":"REFERENCE","title":"招聘管理制度"}', 1, 1, '#', 302, 417, 57, 1, 'system', 'system');
